define("local_transcript/designer",["core/ajax","core/notification"],function(Ajax,Notification){"use strict";const scaleFonts=canvas=>{const scale=canvas.clientWidth/parseFloat(canvas.dataset.pagewidth);canvas.querySelectorAll(".lt-el[data-fontsize]").forEach(el=>{el.style.fontSize=parseFloat(el.dataset.fontsize)*.352778*scale+"px"})},round=value=>Math.round(value*2)/2,makeDraggable=(canvas,el)=>{const followers=()=>document.querySelectorAll('.lt-el[data-followid="'+el.dataset.id+'"]'),place=(left,top)=>{el.style.left=left,el.style.top=top,followers().forEach(follower=>{follower.style.left=left,follower.style.top=top})};el.addEventListener("pointerdown",event=>{event.preventDefault();const scale=canvas.clientWidth/parseFloat(canvas.dataset.pagewidth),startX=event.clientX,startY=event.clientY,originX=parseFloat(el.dataset.posx),originY=parseFloat(el.dataset.posy),regionTop=parseFloat(el.dataset.regiontop),regionHeight=parseFloat(el.dataset.regionheight),pageWidth=parseFloat(canvas.dataset.pagewidth),pageHeight=parseFloat(canvas.dataset.sectionheight),width=parseFloat(el.dataset.width);let moved=!1,posx=originX,posy=originY;el.setPointerCapture(event.pointerId),el.classList.add("lt-dragging");const onMove=moveEvent=>{const dx=moveEvent.clientX-startX,dy=moveEvent.clientY-startY;Math.abs(dx)+Math.abs(dy)>3&&(moved=!0),posx=round(Math.max(0,Math.min(pageWidth-Math.min(width,pageWidth),originX+dx/scale))),posy=round(Math.max(0,Math.min(Math.max(0,regionHeight-1),originY+dy/scale))),place(posx/pageWidth*100+"%",(regionTop+posy)/pageHeight*100+"%")},onUp=()=>{if(el.removeEventListener("pointermove",onMove),el.removeEventListener("pointerup",onUp),el.removeEventListener("pointercancel",onUp),el.classList.remove("lt-dragging"),!moved){window.location.href=el.dataset.editurl;return}Ajax.call([{methodname:"local_transcript_set_element_position",args:{id:parseInt(el.dataset.id,10),posx,posy}}])[0].then(result=>{el.dataset.posx=result.posx,el.dataset.posy=result.posy;const row=document.querySelector('[data-position-for="'+el.dataset.id+'"]');return row&&(row.textContent=result.posx+" / "+result.posy),result}).catch(error=>{place(originX/pageWidth*100+"%",(regionTop+originY)/pageHeight*100+"%"),Notification.exception(error)})};el.addEventListener("pointermove",onMove),el.addEventListener("pointerup",onUp),el.addEventListener("pointercancel",onUp)})};return{init:()=>{document.querySelectorAll(".lt-canvas").forEach(canvas=>{scaleFonts(canvas),window.addEventListener("resize",()=>scaleFonts(canvas)),canvas.querySelectorAll(".lt-el:not([data-followid])").forEach(el=>makeDraggable(canvas,el))})}}});
